// --- UI
const WIZ_STAGES = [["Intent", "what the file is for"], ["File", "drop it or pick an upload"], ["Recognise", "template · source · new"], ["Map", "confirm the fields"], ["Process", "run, store, link"]];
function wizStageSub(W, i) { const I = W.intent ? WIZ_I[W.intent] : null; if (i === 1) return I ? I.label : "choose"; if (i === 2) return W.name ? `${W.name}${W.headers ? ` · ${fmt(W.records.length)} rows · ${W.headers.length} columns` : W.text != null ? ` · ${fmt((W.text || "").length)} characters` : ""}` : "not loaded"; if (i === 3) { const r = W.rec; if (!r) return "waiting for the file"; return r.tier === "known" ? `Known template · ${r.template.name} v${r.template.version || 1}` : r.tier === "variant" ? `Source recognised from ${r.template.name} · ${r.newHeaders.length} new column(s)${r.missing.length ? ` · ${r.missing.length} missing` : ""}` : r.tier === "platform" ? `Source recognised: ${wizPlatLabel(W)}` : r.tier === "workbook" ? "Media plan workbook" : r.tier === "document" ? "Reference document" : W.platform ? `Defined as ${wizPlatLabel(W)}` : "Unknown source — define it"; } if (i === 4) { if (!I) return ""; if (I.nomap || W.noMap) return W.rec ? "no mapping needed" : ""; const n = Object.values(W.mapping || {}).filter(Boolean).length; return W.headers ? `${n} of ${W.headers.length} columns mapped${wizMissing(W).length ? " · missing: " + wizMissing(W).join(", ") : ""}` : ""; } if (i === 5) return W.busy ? "processing…" : W.error ? W.error : W.result ? W.result.summary : (I ? I.saves : ""); return ""; }
function wizStagesHtml(W) { return `<div class="dstages">${WIZ_STAGES.map(([t, d], i) => { const n = i + 1; const st = W.error && n === 5 ? "fail" : n < W.stage ? "done" : n === W.stage ? "cur" : "todo"; return `<div class="dstage ${st}" ${n < W.stage && !W.busy ? `data-w="stage" data-v="${n}"` : ""} title="${esc(d)}"><span class="n">${st === "done" ? "✓" : n}</span><span class="t">${t}</span><span class="s">${esc(wizStageSub(W, n) || d)}</span></div>`; }).join("")}</div>`; }
function wizSrcCard(W) { const p = W.platform && PLATFORM_DOCS[W.platform]; if (!p && !W.platform_name) return ""; const links = p ? p.docs.map(d => `<div>${d.u ? `<a href="${esc(d.u)}" target="_blank" rel="noopener">${esc(d.t)}</a>` : `<b>${esc(d.t)}</b>`} ${d.v ? pill("verified " + WIZ_CHECKED, "ok") : pill("unverified — vendor site not reachable from the build environment", "warn")}<div class="lab">${esc(d.note)}</div></div>`).join("") : `<div class="lab">A new exporter you defined. Map its columns once; the template is saved client-wide.</div>`; return `<div class="dsrc"><div><b>${esc(wizPlatLabel(W))}</b> <span class="lab">${esc(p?.family || "custom")}</span>${p ? `<div class="lab" style="margin-top:4px">${p.fields.filter(f => f.hub).length} of ${p.fields.length} documented columns map to a Hub field · ${p.fields.filter(f => f.v).length} field names verified against an official source</div>` : ""}</div><div class="links">${links}</div></div>`; }
function wizIntentHtml(W) { const areas = ["Plan", "Measure", "Deliver"]; return `<div class="dwin"><h2>What is this file for?</h2><div class="lab">The intent decides which engine runs and what the Hub stores. Recognised files run on their own; new shapes get a suggested mapping to confirm.</div>${areas.map(a => `<div class="lab" style="margin-top:6px;letter-spacing:.08em;text-transform:uppercase;font-size:10.5px">${a}</div><div class="optcards intents">${WIZ_INTENTS.filter(i => i.area === a).map(i => `<div class="optcard ${W.intent === i.key ? "on" : ""}" data-w="intent" data-v="${i.key}"><div class="t">${esc(i.label)}${qi(i.processor + " · stores " + i.saves)}</div><div class="d">${esc(i.desc)}</div><div class="f">${(i.required || []).length ? "needs " + i.required.map(k => HUB_T[k]?.label || k).join(", ") + (i.oneOf ? " + " + i.oneOf.map(k => HUB_T[k]?.label || k).join(" or ") : "") : i.xlsx ? ".xlsx workbook" : i.nomap ? "no mapping" : "map to the field catalogue"}</div></div>`).join("")}</div>`).join("")}</div>`; }
function wizFileHtml(W) { const I = WIZ_I[W.intent]; const ups = live("uploads").filter(u => u.headers && u.text && (!W.client_id || !u.client_id || wizSame(u.client_id, W.client_id))).slice().reverse(); const camps = live("campaigns").filter(c => !W.client_id || wizSame(W.client_id, c.client_id) || c.client_id === W.client_id); return `<div class="dwin"><h2>${esc(I.label)} · the file</h2><div class="frow"><label class="lab">Client / workspace<br><select id="wiz_client" ${inp}><option value="">…</option>${opt(allowedWs(), W.client_id, wsName)}</select></label><label class="lab">Campaign ${I.key === "facts" ? "(required)" : "(optional)"}<br><select id="wiz_camp" ${inp}><option value="">…</option>${opt(camps, W.campaign_id)}</select></label></div>${dropzone("wiz_file", I.xlsx ? "Drop the media plan workbook" : I.key === "document" ? "Drop the document" : "Drop the report", I.xlsx ? ".xlsx · every recognised tab becomes part of the version (plan lines, audience tracker, publisher responses, reach definitions, rates)" : I.key === "document" ? "text, CSV, Markdown or the first sheet of a workbook · stored with the client, searchable and citable" : "CSV or .xlsx (first sheet) · hashed, recognised against this client's templates, then processed as " + I.label.toLowerCase(), {hero: !W.name})}<input type="file" id="wiz_file" accept="${I.xlsx ? ".xlsx,.xls" : ".csv,.txt,.tsv,.md,.xlsx,.xls"}" hidden>${!I.nomap && ups.length ? `<div class="frow"><span class="lab">or an upload already on file:</span><select id="wiz_existing" ${inp}><option value="">…</option>${opt(ups, "", u => `${u.filename} · ${u.rows ?? "?"} rows`)}</select><button class="btn ghost sm" data-w="use_existing">Use this file</button></div>` : ""}${W.name && W.headers ? `<div class="lab">Loaded <b>${esc(W.name)}</b> · ${fmt(W.records.length)} rows · ${W.headers.length} columns</div><div class="scroll"><table><thead><tr>${W.headers.slice(0, 14).map(h => `<th>${esc(h)}</th>`).join("")}${W.headers.length > 14 ? `<th class="lab">+${W.headers.length - 14}</th>` : ""}</tr></thead><tbody>${W.records.slice(0, 4).map(r => `<tr>${W.headers.slice(0, 14).map(h => `<td class="mono">${esc(String(r[h] ?? "").slice(0, 28))}</td>`).join("")}</tr>`).join("")}</tbody></table></div><div class="wizfoot"><button class="btn ghost sm" data-w="stage" data-v="1">‹ Intent</button><span class="spacer"></span><button class="btn sm" data-w="recognise">Recognise ›</button></div>` : ""}</div>`; }
function wizPlatformPickHtml(W) { return `<div class="dwin"><h2>Unknown source — define it</h2><div class="lab">None of this client's templates match these columns and no platform signature fired (${W.headers.length} columns: ${W.headers.slice(0, 8).map(esc).join(" · ")}${W.headers.length > 8 ? " …" : ""}). Say where the report came from; the mapping is then suggested from that platform's dictionary and saved client-wide once you confirm it.</div><div class="optcards">${Object.entries(PLATFORM_DOCS).map(([k, p]) => `<div class="optcard ${W.platform === k ? "on" : ""}" data-w="plat" data-v="${k}"><div class="t">${esc(p.label)}</div><div class="d">${esc(p.family)} · ${p.fields.length} documented columns${p.docs.some(d => d.v) ? " · verified source" : " · unverified"}</div></div>`).join("")}<div class="optcard ${W.platform === "custom" ? "on" : ""}"><div class="t">New platform / exporter</div><div class="d">Name it; its columns are mapped from the generic dictionary and remembered under that name.</div><div class="frow" style="margin-top:6px"><input id="wiz_platname" ${inp} placeholder="e.g. Nexxen weekly export" value="${esc(W.platform_name || "")}"><button class="btn sm" data-w="plat" data-v="custom">Use</button></div></div></div><div class="wizfoot"><button class="btn ghost sm" data-w="stage" data-v="2">‹ File</button><span class="spacer"></span></div></div>`; }
function wizOptsHtml(W) { const I = WIZ_I[W.intent]; const o = W.opts || {}; const O = I.opts || []; if (!O.length && I.key !== "facts") return ""; const plans = live("mplans").filter(m => wizSame(W.client_id, m.client_id) || !W.client_id).sort((a, b) => (b.updated_at || "").localeCompare(a.updated_at || "")); const P = byId("mplans", o.plan_id); const parts = [];
  if (O.includes("plan")) parts.push(`<label class="lab">Media plan${I.key === "interpret" ? " (client context)" : ""}<br><select data-wopt="plan_id" ${inp}><option value="">${I.key === "interpret" ? "none" : "…"}</option>${opt(plans, o.plan_id, p => `${p.name} v${p.version}${byId("clients", p.client_id) ? " · " + wsName(byId("clients", p.client_id)) : ""}`)}</select></label>`);
  if (O.includes("stream")) parts.push(`<label class="lab">Datorama stream (declared, never inferred)<br><select data-wopt="stream_id" ${inp}><option value="">…</option>${opt(live("dat_streams").filter(s => wizSame(P?.client_id || W.client_id, s.client_id) || s.client_id === (P?.client_id || W.client_id)), o.stream_id, s => `${s.stream_name} · units: ${s.units_field || "?"}`)}</select></label>`);
  if (O.includes("rf_source")) parts.push(`<label class="lab">Reach source<br><select data-wopt="rf_source" ${inp}>${Object.entries(RF_SOURCES).map(([k, s]) => `<option value="${k}" ${o.rf_source === k ? "selected" : ""}>${esc(s.label)}</option>`).join("")}</select></label>`);
  if (O.includes("window")) parts.push(`<label class="lab">Window start<br><input data-wopt="win_start" type="date" ${inp} value="${o.win_start || ""}"></label><label class="lab">Window end<br><input data-wopt="win_end" type="date" ${inp} value="${o.win_end || ""}"></label>`);
  if (O.includes("floor")) parts.push(`<label class="lab">Pre-flight divisor floor<br><input data-wopt="floor" ${inp} style="width:80px" value="${esc(o.floor ?? "1.40")}"></label>`);
  if (O.includes("date_format")) parts.push(`<label class="lab">Date format<br><select data-wopt="date_format" ${inp}>${["%Y-%m-%d", "%d/%m/%Y", "%m/%d/%Y"].map(f => `<option ${o.date_format === f ? "selected" : ""}>${f}</option>`).join("")}</select></label>`);
  if (O.includes("doc_kind")) parts.push(`<label class="lab">Document kind<br><select data-wopt="doc_kind" ${inp}>${Object.entries(DOC_KINDS).map(([k, n]) => `<option value="${k}" ${o.doc_kind === k ? "selected" : ""}>${esc(n)}</option>`).join("")}</select></label><label class="lab">Title<br><input data-wopt="doc_title" ${inp} style="width:280px" value="${esc(o.doc_title || "")}"></label>`);
  const hint = O.includes("rf_source") && o.rf_source ? `<div class="lab" style="margin-top:4px"><b>How to pull it:</b> ${esc(RF_SOURCES[o.rf_source]?.pull || "")}</div>` : O.includes("stream") && byId("dat_streams", o.stream_id) ? `<div class="lab" style="margin-top:4px">Units column expected: <b>${esc(byId("dat_streams", o.stream_id).units_field || "Impressions")}</b>${byId("dat_streams", o.stream_id).cost_field ? ` · cost: <b>${esc(byId("dat_streams", o.stream_id).cost_field)}</b>` : ""} — map impressions/units and cost to those.</div>` : "";
  return `<div class="card" style="margin:0"><b style="font-size:13px">Stream settings</b><div class="frow" style="margin-top:6px">${parts.join("")}</div>${hint}</div>`; }
function wizMapHtml(W) { const I = WIZ_I[W.intent]; const rec = W.rec || {}; const targets = wizTargetsFor(W); const groups = I.targets === "fields" ? [...new Set(targets.map(t => t.group))].map(g => [g, targets.filter(t => t.group === g)]) : [["Dimensions", targets.filter(t => t.kind === "dimension")], ["Metrics (additive)", targets.filter(t => t.kind === "metric")], ["Rates (never summed)", targets.filter(t => t.kind === "rate")]]; const TK = Object.fromEntries(targets.map(t => [t.key, t])); const miss = wizMissing(W); const used = {}; Object.values(W.mapping).filter(Boolean).forEach(k => used[k] = (used[k] || 0) + 1); const dup = Object.entries(used).filter(([, n]) => n > 1).map(([k]) => TK[k]?.label || k); const newSet = new Set(rec.newHeaders || []); const missSet = new Set((rec.missing || []).map(normH));
  const recLine = rec.tier === "variant" ? `<div class="find warning"><b class="lvl">NEW SHAPE</b><div>Recognised as <b>${esc(rec.template.name)}</b> (v${rec.template.version || 1}, ${Math.round((rec.coverage || 0) * 100)}% of its columns present). ${rec.newHeaders.length ? `${rec.newHeaders.length} new column(s) are highlighted — map them or leave them ignored.` : ""} ${rec.missing.length ? `${rec.missing.length} column(s) the template mapped are missing: ${rec.missing.map(esc).join(", ")}.` : ""} Confirm to save it as v${(rec.template.version || 1) + 1}.</div></div>` : rec.tier === "platform" ? `<div class="find info"><b class="lvl">SOURCE</b><div>Recognised as <b>${esc(wizPlatLabel(W))}</b> from its column signature — no template for this client yet. The mapping below is suggested from the platform dictionary; confirm it and it is saved client-wide.</div></div>` : rec.tier === "known" ? `<div class="find info"><b class="lvl">KNOWN</b><div>${esc(W.note || "Known template.")}</div></div>` : W.platform ? `<div class="find info"><b class="lvl">DEFINED</b><div>Mapping suggested for <b>${esc(wizPlatLabel(W))}</b> from the generic dictionary — confirm each field.</div></div>` : "";
  const nomap = I.nomap || W.noMap; const table = nomap ? `<div class="lab">${I.key === "plan" ? "Workbooks are read tab by tab — no column mapping." : I.key === "document" ? "Documents are stored as text — no column mapping." : W.platform === "datorama_table" ? "Datorama Table contract recognised — the four-tier QA reads the columns by name." : "Pairwise overlap file (Site A · Site B · Overlap) — read as is."}</div>` : `<div class="wizreq"><span class="lab">Required:</span>${(I.required || []).map(k => pill((TK[k]?.label || k) + (Object.values(W.mapping).includes(k) ? " ✓" : " ✗"), Object.values(W.mapping).includes(k) ? "ok" : "bad")).join("")}${I.oneOf ? pill(I.oneOf.map(k => TK[k]?.label || k).join(" or ") + (I.oneOf.some(k => Object.values(W.mapping).includes(k)) ? " ✓" : " ✗"), I.oneOf.some(k => Object.values(W.mapping).includes(k)) ? "ok" : "bad") : ""}${I.key === "facts" ? pill("day/week · media buy name/key/placement id · ≥1 measurement" + (miss.length ? " ✗" : " ✓"), miss.length ? "bad" : "ok") : ""}${(I.optional || []).map(k => pill(TK[k]?.label || k, Object.values(W.mapping).includes(k) ? "ok" : "dim")).join("")}${dup.length ? pill("mapped twice: " + dup.join(", "), "warn") : ""}</div><div class="scroll"><table class="wizmap"><thead><tr><th>Source column</th><th>Sample</th><th>Type</th><th>Hub field</th><th>Status</th></tr></thead><tbody>${W.headers.map(h => { const k = W.mapping[h] || ""; const c = W.conf?.[h]; const n = normH(h); const isNew = newSet.has(n); return `<tr class="${isNew ? "new" : ""}"><td class="mono" style="font-size:12px">${esc(h)}${W.scale?.[h] ? `<div class="lab">× ${W.scale[h]}</div>` : ""}</td><td class="samp" title="${esc(wizSample(W.records, h))}">${esc(wizSample(W.records, h))}</td><td class="lab">${wizTypeOf(W.records, h)}</td><td><select data-wmap="${esc(h)}" ${inp}><option value="">— ignore —</option>${groups.map(([g, ts]) => `<optgroup label="${esc(g)}">${ts.map(t => `<option value="${t.key}" ${k === t.key ? "selected" : ""}>${esc(t.label)}</option>`).join("")}</optgroup>`).join("")}</select></td><td>${isNew ? pill("new field", "warn") : k ? pill(c === "manual" ? "confirmed" : c === "template" ? "from template" : c === "platform" ? "suggested · platform" : c === "generic" || c === "fuzzy" ? "suggested" : c || "mapped", c === "manual" || c === "template" ? "ok" : "info") : pill("ignored", "dim")}</td></tr>`; }).join("")}${(rec.missing || []).map(h => `<tr class="miss"><td class="mono" style="font-size:12px">${esc(h)}</td><td class="samp">—</td><td class="lab">missing</td><td class="lab">${esc(TK[rec.template.mapping[h]]?.label || rec.template.mapping[h])}</td><td>${pill("not in this file", "warn")}</td></tr>`).join("")}</tbody></table></div>`;
  const tpl = nomap ? "" : `<div class="frow"><label class="lab"><input type="checkbox" id="wiz_savetpl" ${W.saveTpl ? "checked" : ""}> Save this mapping as a client-wide template</label><input id="wiz_tplname" ${inp} style="width:300px" value="${esc(W.tplName || "")}" placeholder="Template name" ${W.saveTpl ? "" : "disabled"}><label class="lab"><input type="checkbox" id="wiz_share" ${W.share ? "checked" : ""} ${W.saveTpl ? "" : "disabled"}> share with every client</label></div>`;
  return `<div class="dwin"><div class="dh"><h2>${esc(I.label)} · ${nomap ? "settings" : "map the columns"}</h2><span class="lab">${esc(W.name)} · ${W.headers ? fmt(W.records.length) + " rows" : fmt((W.text || "").length) + " characters"}</span></div>${wizSrcCard(W)}${recLine}${wizOptsHtml(W)}${table}${tpl}<div class="wizfoot"><button class="btn ghost sm" data-w="stage" data-v="${rec.tier === "unknown" && !nomap ? 3 : 2}">‹ Back</button><span class="lab">${miss.length ? "missing: " + miss.join(", ") : !wizOptsReady(W) ? "choose the settings above" : "ready"}</span><span class="spacer"></span><button class="btn sm" data-w="process" ${miss.length || !wizOptsReady(W) || W.busy ? "disabled" : ""}>${nomap ? "Process" : "Confirm mapping & process"} ›</button></div></div>`; }
function wizResultHtml(W) { const I = WIZ_I[W.intent]; const R = W.result; let body = ""; if (W.busy) body = `<div class="empty"><b>Processing…</b>${esc(I.processor)}</div>`; else if (W.error) body = `<div class="find error"><b class="lvl">ERROR</b><div>${esc(W.error)}</div></div><div class="lab">Fix the mapping or the settings and run it again; nothing partial was stored${I.key === "facts" ? " except the upload record" : ""}.</div>`; else if (R) { if (R.kind === "starter") body = `<div class="topbar">${pill(R.status, stc(R.status))}<span class="lab">Starter delivery suite · ${R.rows} rows · ${R.flagged} flagged</span></div>${findings(R.findings)}`; else if (R.kind === "cboe") body = `<div class="topbar">${pill(R.status, R.status === "PASSED" ? "ok" : R.status === "BLOCKED" ? "bad" : "warn")}<span class="lab">${esc(R.summary)}</span><span class="spacer"></span><a class="btn ghost sm" href="#datorama" data-w="goto_qa" data-v="${R.run_id}">Open the QA run</a></div>`; else if (R.kind === "interpret") body = `<div class="lab">Saved to Reports as an interpretation. <a href="#reports" data-w="goto_report" data-v="${R.report_id}">Open it</a></div>` + pInterpretResult(R.interp).replace(/<div class="frow" style="margin-top:8px">[\s\S]*$/, ""); else if (R.kind === "delivery") body = `<div class="lab">${esc(R.summary)}. <a href="#datorama" data-w="goto_forecast" data-v="${R.plan_id}">Open pacing &amp; forecast</a></div>${R.problems.map(p => `<div class="find warning"><b class="lvl">CHECK</b><div>${esc(p)}</div></div>`).join("")}`; else if (R.kind === "rf") body = `<div class="lab">${esc(R.summary)}. <a href="#plans" data-w="goto_rf" data-v="${R.plan_id}">Open the plan's R&amp;F inputs</a></div>${R.problems.map(p => `<div class="find warning"><b class="lvl">CHECK</b><div>${esc(p)}</div></div>`).join("")}`; else if (R.kind === "benchmarks" && R.pending) { const prop = R.prop; body = `<div class="frow"><span class="lab">Matched dimensions: ${Object.entries(prop.dims).filter(([, h]) => h).map(([k, h]) => `${k} ← ${esc(h)}`).join(" · ") || "none"}</span>${prop.unmatched.dims.length ? pill("not in the pivot: " + prop.unmatched.dims.join(", ") + " — benchmark grain will be coarser", "warn") : ""}<span class="lab">Metrics: ${prop.mets.join(", ")}</span></div><div class="scroll"><table><thead><tr><th>Channel</th><th>Publisher</th><th>Audience</th><th>Format</th><th>Metric</th><th class="num">New value</th><th class="num">Existing target</th></tr></thead><tbody>${prop.rows.slice(0, 60).map(r => `<tr><td>${esc(r.channel)}</td><td>${esc(r.publisher)}</td><td style="font-size:11px">${esc(String(r.audience).slice(0, 40))}</td><td>${esc(r.format)}</td><td class="mono">${esc(r.metric)}</td><td class="num mono">${r.value < 1 ? (r.value * 100).toFixed(2) + "%" : fmt(r.value)}</td><td class="num mono">${r.existing ? (r.existing.target < 1 ? (r.existing.target * 100).toFixed(2) + "%" : fmt(r.existing.target)) + " (" + r.existing.as_of + ")" : "—"}</td></tr>`).join("")}</tbody></table></div><div class="wizfoot"><span class="lab">Ranges, not points — the confirmed value becomes min, target and max until a later upload widens it; superseded values keep their as-of history.</span><span class="spacer"></span><button class="btn sm" data-w="bm_confirm">Confirm ${prop.rows.length} benchmark(s)${prop.rows.some(r => r.existing) ? ` — supersedes ${prop.rows.filter(r => r.existing).length}` : ""}</button></div>`; } else if (R.kind === "benchmarks") body = `<div class="lab">${esc(R.summary)}. <a href="#datorama" data-w="goto_bm" data-v="${R.plan_id}">Open the benchmark bank</a></div>`; else if (R.kind === "facts") body = `<div class="lab">${esc(R.summary)}. <a href="#pivot">Open Pivot</a> · <a href="#campaigns" data-w="goto_map" data-v="${R.upload_id}">Open the upload in Campaigns</a></div>`; else if (R.kind === "plan") body = `<div class="lab">${esc(R.summary)}. <a href="#plans" data-w="goto_plan" data-v="${R.plan_id}">Open the plan</a></div>`; else if (R.kind === "document") body = `<div class="lab">${esc(R.summary)}. <a href="#datorama" data-w="goto_docs">Open the document library</a></div>`; }
  const tplLine = W.tpl ? `<div class="lab">Template: <b>${esc(W.tpl.name)}</b> v${W.tpl.version || 1}${W.tpl.share_all ? " · shared with every client" : " · this client"} — the next file with these columns runs on its own.</div>` : ""; return `<div class="dwin"><div class="dh"><h2>${esc(I.label)} · ${W.busy ? "processing" : W.error ? "not processed" : R?.pending ? "awaiting confirmation" : "processed"}</h2><span class="lab">${esc(W.name)}${W.rec?.tier === "known" ? " · ran automatically from a known template" : ""}</span></div>${body}${tplLine}<div class="wizfoot">${!I.nomap && !W.noMap ? `<button class="btn ghost sm" data-w="remap">‹ Re-map</button>` : `<button class="btn ghost sm" data-w="stage" data-v="2">‹ File</button>`}<span class="spacer"></span><button class="btn sm" data-w="new">New data stream</button></div></div>`; }
function wizListsHtml() { const ups = live("uploads").filter(u => u.intent && (!V.ws || !u.client_id || wizSame(u.client_id, V.ws))).slice().reverse(); const tpls = live("upload_templates").filter(t => !V.ws || t.share_all || wizSame(t.client_id, V.ws)); const tierLab = t => ({known: "known template", variant: "new shape", platform: "source recognised", unknown: "defined", workbook: "workbook", document: "document"})[t] || t || "—";
  return `<div class="card"><div class="topbar"><b>Streams processed</b><span class="lab">${ups.length} · every file that went through the stages, with what it was for and what it produced</span></div><table><thead><tr><th>File</th><th>Intent</th><th>Source</th><th>Recognition</th><th>Result</th><th>When</th><th></th></tr></thead><tbody>${ups.slice(0, 40).map(u => `<tr><td><b>${esc(u.filename)}</b><div class="lab">${esc(byId("clients", u.client_id) ? wsName(byId("clients", u.client_id)) : "—")}${u.campaign_id ? " · " + esc(byId("campaigns", u.campaign_id)?.name || "") : ""}</div></td><td>${pill(WIZ_I[u.intent]?.label || u.intent, "info")}</td><td class="lab">${esc(u.platform_label || PLATFORM_DOCS[u.platform]?.label || "—")}</td><td class="lab">${esc(tierLab(u.wiz?.tier))}${u.wiz?.template_name ? `<div class="lab">${esc(u.wiz.template_name)}</div>` : ""}</td><td style="font-size:12px">${u.wiz?.status === "awaiting confirmation" ? pill("awaiting confirmation", "warn") : ""} ${esc(u.wiz?.summary || u.status || "")}</td><td class="lab">${(u.wiz?.processed_at || u.updated_at || "").slice(0, 16).replace("T", " ")}</td><td>${u.text ? `<button class="btn ghost xs" data-w="rerun" data-v="${u.id}">Run again</button>` : ""}</td></tr>`).join("") || `<tr><td colspan="7" class="lab">Nothing yet — start a data stream above.</td></tr>`}</tbody></table></div>
  <div class="card"><div class="topbar"><b>Templates · client-wide recognition</b><span class="lab">${tpls.length} · a file whose columns match one of these runs without a mapping step</span></div><table><thead><tr><th>Template</th><th>Intent</th><th>Source</th><th>Scope</th><th class="num">Columns mapped</th><th class="num">Used</th><th>Last used</th><th></th></tr></thead><tbody>${tpls.map(t => `<tr><td><b>${esc(t.name)}</b> <span class="lab">v${t.version || 1}</span></td><td>${pill(WIZ_I[t.intent]?.label || t.intent, "info")}</td><td class="lab">${esc(t.platform_label || PLATFORM_DOCS[t.platform]?.label || "—")}</td><td class="lab">${t.share_all ? "every client" : esc(byId("clients", t.client_id) ? wsName(byId("clients", t.client_id)) : "—")}</td><td class="num">${Object.keys(t.mapping || {}).length} / ${(t.headers || []).length}</td><td class="num">${t.uses || 0}</td><td class="lab">${esc(t.last_used || "")}</td><td><button class="btn ghost xs" data-w="tpl_trash" data-v="${t.id}" title="the next file with these columns will ask for its mapping again">Retire</button></td></tr>`).join("") || `<tr><td colspan="8" class="lab">No templates yet — the first confirmed mapping creates one.</td></tr>`}</tbody></table></div>`; }
function wizDictHtml() { return `<div class="card wizdict"><div class="topbar"><b>Platform dictionary</b><span class="lab">what each exporter's report carries → the Hub field it maps to · sources checked ${WIZ_CHECKED}; unverified entries are working names to confirm at the link</span><span class="spacer"></span><button class="btn ghost xs" data-w="dict">Close</button></div><div style="display:grid;gap:8px">${Object.entries(PLATFORM_DOCS).map(([k, p]) => `<details><summary>${esc(p.label)} <span class="lab">${esc(p.family)} · ${p.fields.length} columns · ${p.fields.filter(f => f.v).length} verified</span></summary><div class="lab" style="margin:6px 0">${p.docs.map(d => `<div>${d.u ? `<a href="${esc(d.u)}" target="_blank" rel="noopener">${esc(d.t)}</a>` : `<b>${esc(d.t)}</b>`} ${d.v ? pill("verified " + WIZ_CHECKED, "ok") : pill("unverified", "warn")}<div>${esc(d.note)}</div></div>`).join("")}</div><table><thead><tr><th>Export column</th><th>Hub field</th><th>Kind</th><th>Note</th><th>Name verified</th></tr></thead><tbody>${p.fields.map(f => `<tr><td class="mono" style="font-size:11px">${esc(f.n)}</td><td>${f.hub ? esc(HUB_T[f.hub]?.label || f.hub) : `<span class="lab">— (not mapped)</span>`}</td><td class="lab">${f.k}${f.scale ? ` · × ${f.scale}` : ""}</td><td style="font-size:12px">${esc(f.note || "")}</td><td>${f.v ? pill("yes", "ok") : pill("working name", "dim")}</td></tr>`).join("")}</tbody></table></details>`).join("")}</div><div class="lab" style="margin-top:8px">Hub fields: ${HUB_TARGETS.map(t => `<span class="mono">${esc(t.label)}</span>`).join(" · ")}. Reach-type fields are never summed across rows or periods; rates are recomputed from their components.</div></div>`; }
function wizWindowHtml(W) { return W.stage === 1 ? wizIntentHtml(W) : W.stage === 2 ? wizFileHtml(W) : W.stage === 3 ? wizPlatformPickHtml(W) : W.stage === 4 ? wizMapHtml(W) : wizResultHtml(W); }
function pUploadWizard(host) { const W = V.wiz || wizReset(); const win = wizWindowHtml(W); const head = host === "reports" ? `<div class="dh" style="display:flex;align-items:center;gap:10px;flex-wrap:wrap"><b style="font-size:15px">Data streams</b><span class="lab">declare the intent · drop the file · recognised files run themselves · new shapes get a suggested mapping to confirm</span><span class="spacer"></span><button class="btn ghost sm" data-w="dict">Platform dictionary</button><button class="btn sm" data-w="new">New data stream</button></div>` : ""; return `${head}<div class="dstream">${wizStagesHtml(W)}${win}</div>${V.wizDict ? wizDictHtml() : ""}${wizListsHtml()}`; }
function pUploads() { return `<div class="topbar"><h1>Data streams</h1><span class="lab">declare the intent · drop the file · recognised files run themselves · new shapes get a suggested mapping to confirm</span><span class="spacer"></span><button class="btn ghost sm" data-w="dict">Platform dictionary</button><button class="btn sm" data-w="new">New data stream</button></div>` + pUploadWizard("page"); }

// --- events
document.addEventListener("click", async e => { const b = e.target.closest("[data-w]"); if (!b) return; const a = b.dataset.w, v = b.dataset.v; const W = V.wiz || wizReset(); try {
  if (a === "new") { wizReset(); } else if (a === "dict") { V.wizDict = !V.wizDict; }
  else if (a === "intent") { const changed = W.intent !== v; W.intent = v; W.result = null; W.error = null; W.stage = 2; if (changed && W.headers && W.text != null) { render(); await wizAfterLoad(W); return; } if (changed && W.text != null && WIZ_I[v].key === "document") { render(); await wizLoadText(W, W.text); return; } }
  else if (a === "stage") { if (W.busy) return; W.stage = +v; W.error = null; if (+v <= 4) W.result = null; }
  else if (a === "recognise") { if (!W.headers) return toast("Load a file first."); render(); await wizAfterLoad(W); return; }
  else if (a === "use_existing") { const u = byId("uploads", val("wiz_existing")); if (!u) return toast("Pick an upload."); W.file = null; W.name = u.filename; W.result = null; W.error = null; W.remapped = false; if (!W.client_id && u.client_id) W.client_id = u.client_id; if (!W.campaign_id && u.campaign_id) W.campaign_id = u.campaign_id; render(); await wizLoadText(W, u.text); return; }
  else if (a === "plat") { wizPickPlatform(W, v, v === "custom" ? val("wiz_platname") : ""); }
  else if (a === "process") { if (wizMissing(W).length) return toast("Map the required fields first: " + wizMissing(W).join(", ")); if (!wizOptsReady(W)) return toast("Choose the settings first."); W.remapped = W.rec?.tier === "known" ? W.remapped : true; await wizProcess(W); return; }
  else if (a === "remap") { if (W.busy) return; W.stage = 4; W.result = null; W.error = null; W.remapped = true; W.saveTpl = true; W.tplName = W.tplName || wizDefaultTplName(W); }
  else if (a === "bm_confirm") { if (!W.bm) return; await wizConfirmBenchmarks(W); }
  else if (a === "rerun") { const u = byId("uploads", v); if (!u?.text) return toast("That file's text is not stored — drop it again."); wizReset(u.intent); const W2 = V.wiz; W2.client_id = u.client_id || W2.client_id; W2.campaign_id = u.campaign_id || ""; W2.name = u.filename; W2.file = null; render(); await wizLoadText(W2, u.text); return; }
  else if (a === "tpl_trash") { if (!confirm("Retire this template? The next file with these columns will ask for its mapping again.")) return; await trash("upload_templates", v); toast("Template retired."); }
  else if (a === "goto_qa") { V.datMode = "qa"; V.qaOpen = v; V.mpOpen = null; return; } else if (a === "goto_report") { V.repTab = "stored"; V.repOpen = v; return; } else if (a === "goto_forecast") { V.mpOpen = null; V.datPlan = v; V.datMode = "forecast"; return; } else if (a === "goto_rf") { V.mpOpen = v; V.mpTab = "reconcile"; return; } else if (a === "goto_bm") { V.datPlan = v; V.datMode = "benchmarks"; return; } else if (a === "goto_map") { V.sel = v; V.mode = "map"; return; } else if (a === "goto_plan") { V.mpOpen = v; V.mpTab = "overview"; return; } else if (a === "goto_docs") { V.datMode = "docs"; return; }
  else return; render(); } catch (err) { console.error(err); toast("Error: " + (err.message || err)); } });
document.addEventListener("change", async e => { const t = e.target; const W = V.wiz; if (!W) return;
  if (t.id === "wiz_file") { const f = t.files[0]; if (!f) return; try { await wizLoadFile(f); } catch (err) { console.error(err); toast("Error: " + (err.message || err)); } return; }
  if (t.id === "wiz_client") { W.client_id = t.value; W.campaign_id = ""; render(); return; } if (t.id === "wiz_camp") { W.campaign_id = t.value; return; }
  if (t.dataset.wmap != null) { const h = t.dataset.wmap; W.mapping[h] = t.value; W.conf[h] = t.value ? "manual" : null; W.remapped = true; if (!t.value) delete W.scale[h]; render(); return; }
  if (t.dataset.wopt != null) { W.opts[t.dataset.wopt] = t.value; if (["plan_id", "stream_id", "rf_source"].includes(t.dataset.wopt)) render(); return; }
  if (t.id === "wiz_savetpl") { W.saveTpl = t.checked; render(); return; } if (t.id === "wiz_tplname") { W.tplName = t.value; return; } if (t.id === "wiz_share") { W.share = t.checked; return; } });
